//! The generated test driver, axiom guard and run executable (definition-independent apart from
//! the namespace and the top sort).

pub fn lakefile(ns: &str, prelude: &str, exe: &str) -> String {
    format!(
        "import Lake\nopen Lake DSL\n\n/-- Generated by k2lean; do not edit. -/\npackage «{ns}» where\n  leanOptions := #[⟨`autoImplicit, false⟩]\n\n\
require KPrelude from \"{prelude}\"\n\n\
/-- The generated semantics: terms, functions, rules, adequacy, determinism. -/\n@[default_target]\nlean_lib {ns}\n\n\
/-- Golden cases (`k2lean goldens` writes `{ns}Test/Goldens.lean`) and the axiom guard. -/\nlean_lib {ns}Test\n\n\
/-- `lake test`: run every golden case through `run`. -/\n@[test_driver]\nlean_exe «{exe}-test» where\n  root := `{ns}Test.Main\n\n\
/-- Named initial configurations (`k2lean configs` writes `{ns}Bench/Programs.lean`). -/\nlean_lib {ns}Bench\n\n\
/-- `{exe}-run NAME [FUEL]`: run a named configuration, print steps, status, time and the result. -/\nlean_exe «{exe}-run» where\n  root := `{ns}Bench.Main\n"
    )
}

pub fn test_main(ns: &str, top: &str) -> String {
    format!(
        r#"import {ns}Test.Goldens
import {ns}Test.Traces
import {ns}Test.Axioms

/-! Generated by k2lean; do not edit. `lake test`. -/

open {ns} {ns}Test KPrelude

def goldenFuel : Nat := 10000000

def statusStr : Status → String
  | .final => "final"
  | .stuck => "stuck (no rule applies)"
  | .undefined r => s!"undefined step (rule {{r}})"
  | .outOfFuel => "out of fuel"

/-- `none` on success, else an explanation. -/
def check (g : Golden) : Option String :=
  let r := run goldenFuel g.init
  match g.expected with
  | .config c =>
    match r.status with
    | .stuck =>
      if r.config = c then none
      else some s!"final configuration differs after {{r.steps}} steps\n    Lean: {{toK_{top} r.config}}\n    K:    {{toK_{top} c}}"
    | st => some s!"K ended in a final configuration, the run ended {{statusStr st}} after {{r.steps}} steps"
  | .failure msg =>
    match r.status with
    | .undefined _ => none
    | st => some s!"K failed ({{msg}}), the run ended {{statusStr st}}"

def describe (g : Golden) : String :=
  let r := run goldenFuel g.init
  s!"{{r.steps}} steps, {{statusStr r.status}}"

/-- Compare `run i` with the recorded configuration after `i` steps. -/
def checkTrace (init : {top}) (states : List (Nat × {top})) : List String :=
  states.filterMap fun (i, s) =>
    let r := run i init
    if r.config = s then none
    else some s!"after {{i}} steps: Lean ({{r.steps}} steps) {{toK_{top} r.config}}, recorded {{toK_{top} s}}"

def tomlStr (s : String) : String := "\"" ++ (s.replace "\\" "\\\\").replace "\"" "\\\"" ++ "\""

/-- `--toml FILE` also writes one `[[case]]` table per golden case. -/
def main (args : List String) : IO UInt32 := do
  let mut failed := 0
  let mut passed := 0
  let mut toml := ""
  for g in goldens do
    let r := run goldenFuel g.init
    let res := check g
    toml := toml ++ s!"[[case]]\nname = {{tomlStr g.name}}\ngroup = {{tomlStr g.group}}\npass = {{res.isNone}}\nsteps = {{r.steps}}\noutcome = {{tomlStr (statusStr r.status)}}\n\n"
    match res with
    | none =>
      passed := passed + 1
      IO.println s!"PASS {{g.group}}/{{g.name}}: {{describe g}}"
    | some why =>
      failed := failed + 1
      IO.println s!"FAIL {{g.group}}/{{g.name}}: {{why}}"
  match args with
  | ["--toml", path] => IO.FS.writeFile path toml
  | _ => pure ()
  IO.println s!"goldens: {{passed}}/{{goldens.length}} pass"
  for (name, engine, states) in traces do
    match goldens.find? (·.name == name) with
    | none => IO.println s!"FAIL trace {{name}}: no such case"; failed := failed + 1
    | some g =>
      let bad := checkTrace g.init states
      if bad.isEmpty then
        IO.println s!"PASS trace {{name}} vs {{engine}}: {{states.length}} configurations equal (after 0..{{(states.getLast?.map (·.1)).getD 0}} steps)"
      else
        failed := failed + 1
        IO.println s!"FAIL trace {{name}} vs {{engine}}: {{bad.head!}}"
  if failed == 0 then IO.println "PASS" else IO.println s!"FAIL ({{failed}})"
  return if failed == 0 then 0 else 1
"#
    )
}

/// The modules the guard imports besides the library's root: the per-rule preservation
/// principle and, when the definition has one, the initial configuration (neither is imported
/// by the root, so a user of the library builds them only when importing them).
fn guard_imports(ns: &str, init: bool) -> String {
    let mut s = format!("import {ns}\nimport {ns}.Preserves\n");
    if init {
        s.push_str(&format!("import {ns}.Init\n"));
    }
    s
}

/// The axiom guard; `multi`: the theorems of a definition with several-match rules; `init`: the
/// library has `{ns}.Init`.
pub fn axioms_with(ns: &str, extra: &[String], ranked: bool, multi: bool, init: bool) -> String {
    let imports = guard_imports(ns, init);
    if multi {
        let mut more = String::new();
        for chunk in extra.chunks(8) {
            let names: Vec<String> = chunk.iter().map(|n| format!("{ns}.{n}")).collect();
            more.push_str(&format!("#k2l_assert_axioms {}\n", names.join(" ")));
        }
        return format!(
            "{imports}\n/-! Generated by k2lean; do not edit. Build-time guard: the main theorems use only\n`propext`, `Quot.sound` and `Classical.choice` (no `sorryAx`, no added axioms). -/\n\nopen {ns} KPrelude\n\n{}#k2l_assert_axioms {ns}.ser_SortKItem_inj\n#k2l_assert_axioms {ns}.Step.preserves_of\n{more}",
            crate::multi::axioms_core(ns)
        );
    }
    let mut more = String::new();
    for chunk in extra.chunks(8) {
        let names: Vec<String> = chunk.iter().map(|n| format!("{ns}.{n}")).collect();
        more.push_str(&format!("#k2l_assert_axioms {}\n", names.join(" ")));
    }
    let core = if ranked {
        format!(
            "#k2l_assert_axioms {ns}.step_sound {ns}.step_progress {ns}.step_stuck {ns}.stuck_no_step {ns}.run_sound {ns}.Step0.lift {ns}.Step.base\n"
        )
    } else {
        format!(
            "#k2l_assert_axioms {ns}.step_sound {ns}.successors_iff {ns}.step_progress {ns}.step_stuck {ns}.stuck_no_step {ns}.step_undefined {ns}.run_sound\n#k2l_assert_axioms {ns}.rules_complete {ns}.rules_applies {ns}.Step.app\n"
        )
    };
    format!(
        "{imports}\n/-! Generated by k2lean; do not edit. Build-time guard: the main theorems use only\n`propext`, `Quot.sound` and `Classical.choice` (no `sorryAx`, no added axioms). -/\n\n\
open {ns} KPrelude\n\n\
{core}\
#k2l_assert_axioms {ns}.Step.deterministic {ns}.step_complete {ns}.step_iff\n\
#k2l_assert_axioms {ns}.ser_SortKItem_inj\n\
#k2l_assert_axioms {ns}.Step.preserves_of\n{more}"
    )
}

pub fn bench_main(ns: &str, top: &str) -> String {
    format!(
        r#"import {ns}Bench.Programs

/-! Generated by k2lean; do not edit. `{ns}-run NAME [FUEL]`. -/

open {ns} {ns}Bench KPrelude

def main (args : List String) : IO UInt32 := do
  match args with
  | [] | ["--list"] =>
    for (n, _) in programs do IO.println n
    return 0
  | name :: rest =>
    let fuel := (rest.head? >>= String.toNat?).getD 1000000000
    match programs.find? (·.1 == name) with
    | none => IO.eprintln s!"unknown program {{name}}"; return 2
    | some (_, c) =>
      let t0 ← IO.monoNanosNow
      -- `IO.lazyPure` keeps the run inside the timed region
      let r ← IO.lazyPure fun _ => run fuel c
      if r.steps == 0 && r.status == .outOfFuel then IO.eprintln "no step taken"
      let steps := r.steps
      let t1 ← IO.monoNanosNow
      let st := match r.status with
        | .stuck => "stuck" | .final => "final" | .undefined n => s!"undefined {{n}}" | .outOfFuel => "out-of-fuel"
      IO.println s!"status: {{st}}"
      IO.println s!"steps: {{steps}}"
      IO.println s!"time_ms: {{(t1 - t0).toFloat / 1000000.0}}"
      IO.println s!"config: {{toK_{top} r.config}}"
      return 0
"#
    )
}
